import { gunzipSync } from "node:zlib";

/** Frozen bytes from commit 96155af. Protocol 3 accidentally hashed these nine
 * tracked runtime artifacts. Keep their historical contributions without reading
 * mutable local databases/logs, requiring Git at runtime, or aliasing hashes.
 * They are compatibility constants, not semantic benchmark inputs. */
const historicalRuntimeGzip: Record<string, string> = {
  "evals/000-fundamentals/005-function_calling/answer/backend.stderr.log":
    "H4sIAAAAAAACEwMAAAAAAAAAAAA=",
  "evals/000-fundamentals/005-function_calling/answer/backend.stdout.log":
    "",
  "evals/000-fundamentals/005-function_calling/answer/convex_local_backend.sqlite3":
    "",
  "evals/000-fundamentals/008-helper_fns/answer/backend.stderr.log":
    "H4sIAAAAAAACEwMAAAAAAAAAAAA=",
  "evals/000-fundamentals/008-helper_fns/answer/backend.stdout.log":
    "",
  "evals/000-fundamentals/008-helper_fns/answer/convex_local_backend.sqlite3":
    "",
  "evals/000-fundamentals/009-returns_validator/answer/backend.stderr.log":
    "H4sIAAAAAAACEwMAAAAAAAAAAAA=",
  "evals/000-fundamentals/009-returns_validator/answer/backend.stdout.log":
    "",
  "evals/000-fundamentals/009-returns_validator/answer/convex_local_backend.sqlite3":
    "",
};

export const legacyRuntimeContributions = new Map(
  Object.entries(historicalRuntimeGzip).map(([path, gzip]) => [
    path,
    gunzipSync(Buffer.from(gzip, "base64")),
  ]),
);
